CREATE TABLE IF NOT EXISTS research_papers (
  id INTEGER PRIMARY KEY,
  title TEXT NOT NULL,
  authors TEXT,
  year INTEGER,
  category TEXT,
  abstract TEXT,
  pdf_url TEXT,
  citation TEXT
);

INSERT INTO research_papers (id,title,authors,year,category,abstract,pdf_url,citation) VALUES (1,'Automated Drainage Cleaner with Water Level Monitoring and SMS Flood Alert System','Silongan, M. J. A., Lorenzo, C. S. B., Gamus, E. D. C., Mariposque, C. J. A., Romano, R. C., Masangya, R. A., Maguana, G. E., & Pene, J. A.',2025,'Environment & Disaster Management','This project study designs and develops an automated drainage cleaner to clear blockages, combined with real-time water level monitoring and a GSM-based SMS flood alert system to mitigate urban flooding and protect vulnerable communities in Davao City[cite: 1].','#','Silongan, M. J. A., et al. (2025). Automated Drainage Cleaner with Water Level Monitoring and SMS Flood Alert System. City College of Davao, Bachelor of Technical Vocational Teacher Education[cite: 1].');
INSERT INTO research_papers (id,title,authors,year,category,abstract,pdf_url,citation) VALUES (2,'Smart Flood Alert System','Quibol, P. J. B., Gamboa, J. A. B., Demeterio, B. M. J., Escobarte, L. A. M., Felizarta, R. I. A., Bacurnay, C. P., Batitay, M. S., & Teofilo, J. R.',2025,'Environment & Disaster Management','An affordable, community-based early warning system designed to detect rising water levels and identify human presence in danger zones using PIR motion detection, audible alarms, and SMS notifications to prevent casualties during flash floods[cite: 2].','#','Quibol, P. J. B., et al. (2025). Smart Flood Alert System. City College of Davao, Bachelor of Technical Vocational Teacher Education[cite: 2].');
INSERT INTO research_papers (id,title,authors,year,category,abstract,pdf_url,citation) VALUES (3,'Smart Ventilation Control System for Chicken Factories','Perez, C. J., Petallar, J. P., Quicoy, A. M., Autida, R. M., Drama, A., Baldovi, J., & Onio, G.',2025,'Agriculture','An IoT-driven agricultural automation project aimed at reducing heat stress and managing air quality (such as ammonia and humidity levels) in poultry housing through automated temperature monitoring and ventilation control[cite: 3].','#','Perez, C. J., et al. (2025). Smart Ventilation Control System for Chicken Factories. City College of Davao, Bachelor of Technical Vocational Teacher Education[cite: 3].');
INSERT INTO research_papers (id,title,authors,year,category,abstract,pdf_url,citation) VALUES (4,'SmartFish: A Sustainable and Innovative System for Real-Time Water Level Monitoring, Smart Filtration, and Automated Fish Farm Maintenance','Batucan, M. F. V., Magayo, L. L., Turnos, D. N. L., Pagat, A. K. R., Castillo, M. E., Malanas, D. F. A., Talay, R. F., Corlit, R. R. A., & Flores, H. C.',2025,'Agriculture','A sustainable aquaculture solution integrating automated water level sensing, smart filtration/recycling mechanisms, and automated feeding to enhance fish yield, reduce water contamination, and modernize traditional fish farming operations.','#','Batucan, M. F. V., et al. (2025). SmartFish: A Sustainable and Innovative System for Real-Time Water Level Monitoring, Smart Filtration, and Automated Fish Farm Maintenance. City College of Davao, Bachelor of Technical Vocational Teacher Education.');
INSERT INTO research_papers (id,title,authors,year,category,abstract,pdf_url,citation) VALUES (5,'pH Level Monitoring System and Drainer for Aquaculture','Coscos, K. D. M. C., Echavez, C. A. A., Guiang, G. A. O., Concellado, C. J. R., Bermudez, G. P., Alfafara, C. A., Fulguerinas, J. H., & Elivera, C. R.',2025,'Agriculture','An IoT-based system for fish farms that continuously measures pond water pH with a sensor controlled by an Arduino Uno and shows the reading on an LCD. When pH becomes unsafe, a SIM800L GSM module sends SMS alerts to the owner, and a servo motor opens a gate to drain the water, closing it again once pH returns to normal. The study tests real-time monitoring, sensor accuracy and drainage effectiveness as a low-cost alternative to manual pH testing for small to medium-sized fish farms.','#','Coscos, K. D. M. C., Echavez, C. A. A., Guiang, G. A. O., Concellado, C. J. R., Bermudez, G. P., Alfafara, C. A., Fulguerinas, J. H., & Elivera, C. R. (2025). pH Level Monitoring System and Drainer for Aquaculture. City College of Davao, Bachelor of Technical Vocational Teacher Education.');
